    // GENERAR REPORTE DE TODOS LOS TIQUETES
    function generarReporte() {

        // Obtener TODOS los tiquetes almacenados
        const tiquetes = obtenerTiquetes();

        // Verificar que existan registros
        if (tiquetes.length === 0) {
            alert(""No hay tiquetes registrados para generar el ");
            WriteLiteral(@"reporte."");
            return;
        }

        // Encabezados del reporte
        const encabezados = [
            ""Título"",
            ""Descripción"",
            ""Categoría"",
            ""Técnico asignado"",
            ""Estado""
        ];

        // Obtener toda la información
        const filas = tiquetes.map(tiquete => [

            tiquete.titulo || """",
            tiquete.descripcion || """",
            tiquete.categoria || """",
            tiquete.tecnicoAsignado || ""Sin asignar"",
            tiquete.estado || ""Abierto""

        ]);

        // Convertir los datos a formato CSV
        const contenido = [encabezados, ...filas]
            .map(fila =>
                fila.map(valor =>
                    '""' + String(valor).replace(/""/g, '""""') + '""'
                ).join("";"")
            )
            .join(""\r\n"");

        // Crear archivo descargable
        const archivo = new Blob(
            [""\uFEFF"" + contenido],
            { type: ""text/csv;charset=");
            WriteLiteral(@"utf-8;"" }
        );

        // Crear enlace de descarga
        const enlace = document.createElement(""a"");

        const url = URL.createObjectURL(archivo);

        enlace.href = url;
        enlace.download = ""Reporte_Tiquetes_HelpDesk.csv"";

        document.body.appendChild(enlace);

        enlace.click();

        document.body.removeChild(enlace);

        URL.revokeObjectURL(url);

        // Confirmar descarga
        alert(""¡Reporte generado correctamente!\nTotal de tiquetes: "" + tiquetes.length);
    }


